@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=dog
@r1.c1 w.request.constraint request=$r1 on=place attribute=drawn.relation value="in front of" words="in front of the house" operator=relation phase=result open_value=true
@r1.c2 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the house" operator=relation phase=selector
@r1.c3 w.request.constraint request=$r1 on=size attribute=drawn.size value=small operator=degree phase=result
@r2 w.request.request act=change mood=do words="make it face right" predicate=make
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=context description=it
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=drawn.facing value=right operator=eq phase=result key_words=face

@r1 w.request.request act=make mood=do words="put a small dog in front of the house" predicate=put
@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=dog
@r1.c1 w.request.constraint request=$r1 on=place attribute=drawn.relation value="in front of" words="in front of the house" operator=relation phase=result open_value=true
@r1.c2 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the house" operator=relation phase=selector
@r1.c3 w.request.constraint request=$r1 on=size attribute=drawn.size value=small operator=degree phase=result
@r2 w.request.request act=change mood=do words="facing right" predicate=facing
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=context
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=drawn.facing value=right operator=eq phase=result

@r1 w.request.request act=make mood=do words="add a dog in front of the house" predicate=add
@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=dog
@r1.c1 w.request.constraint request=$r1 on=place attribute=drawn.relation value="in front of" words="in front of the house" operator=relation phase=result open_value=true
@r1.c2 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the house" operator=relation phase=selector
@r2 w.request.request act=change mood=do words="turn it right" predicate=turn
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=context description=it
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=drawn.facing value=right operator=eq phase=result
